2026-11-04T04:56:52.9995558Z with:
2026-11-04T04:56:53.0035355Z   script: const CLA_VERSION = '2026-08-28-draft';
const SIGN_PHRASE = 'I have read the CLA Document and I hereby sign the CLA';
const SIGNATURES_BRANCH = 'cla-signatures';
const SIGNATURES_PATH = 'signatures.json';
const MARKER = '<!-- overlay-cla -->';
const CHECK_NAME = 'CLA Signatures';
const ALLOWLIST = new Set([
  'developedbydev',
  'dependabot[bot]',
  'dependabot',
  'github-actions[bot]',
]);

const { owner, repo } = context.repo;
// Merge-group checks verify existing signatures; this path never
// records a legal signature or posts a signature comment.
if (context.eventName === 'merge_group') {
  const group = context.payload.merge_group;
  if (!group || !/^[a-f0-9]{40}$/.test(group.base_sha || '') ||
      !/^[a-f0-9]{40}$/.test(group.head_sha || '') ||
      group.base_ref !== 'refs/heads/main') {
    core.setFailed('Invalid merge-group provenance.');
    return;
  }
  const { registry } = await loadRegistry();
  const signed = signedLoginsForCurrentVersion(registry.signatures);
  const missing = new Set();
  let inspected = 0;
  for (let page = 1; ; page++) {
    const { data } = await github.rest.repos.compareCommitsWithBasehead({
      owner, repo, basehead: `${group.base_sha}...${group.head_sha}`,
      per_page: 100, page,
    });
    if (!['ahead', 'identical'].includes(data.status)) {
      core.setFailed('Merge-group head is not descended from its base.');
      return;
    }
    for (const commit of data.commits) {
      inspected++;
      const login = commit.author?.login || commit.committer?.login;
      if (login && login !== 'web-flow') {
        if (!isAllowlisted(login) && !signed.has(login.toLowerCase())) missing.add(login);
        continue;
      }
      // The event-authenticated head is GitHub's synthetic merge.
      if (commit.sha === group.head_sha && commit.parents?.length >= 2) continue;
      const associated = await github.paginate(github.rest.repos.listPullRequestsAssociatedWithCommit, {
        owner, repo, commit_sha: commit.sha, per_page: 100,
      });
      let exempt = false;
      for (const pr of associated) {
        if (pr.base?.repo?.full_name !== `${owner}/${repo}` || !isAllowlisted(pr.user?.login)) continue;
        const commits = await github.paginate(github.rest.pulls.listCommits, {
          owner, repo, pull_number: pr.number, per_page: 100,
        });
        if (commits.some(candidate => candidate.sha === commit.sha)) { exempt = true; break; }
      }
      if (!exempt) missing.add(`unidentified commit ${commit.sha.slice(0, 12)}`);
    }
    if (data.commits.length < 100) break;
  }
  if (inspected === 0 || missing.size) {
    core.setFailed(missing.size
      ? `Merge-group CLA signatures missing: ${[...missing].join(', ')}`
      : 'Merge-group contained no verifiable commits.');
    return;
  }
  core.info(`Verified existing CLA signatures for ${inspected} merge-group commits.`);
  return;
}

const pullNumber =
  context.payload.pull_request?.number ?? context.payload.issue?.number;
if (!pullNumber) {
  core.setFailed('CLA check could not determine the pull request number.');
  return;
}

function isAllowlisted(login) {
  const normalized = String(login || '').toLowerCase();
  return ALLOWLIST.has(normalized) || normalized.endsWith('[bot]');
}

function signedLoginsForCurrentVersion(signatures) {
  return new Set(
    signatures
      .filter((entry) => entry.claVersion === CLA_VERSION)
      .map((entry) => String(entry.githubUser || '').toLowerCase()),
  );
}

async function loadRegistry() {
  try {
    const { data } = await github.rest.repos.getContent({
      owner,
      repo,
      path: SIGNATURES_PATH,
      ref: SIGNATURES_BRANCH,
    });
    const parsed = JSON.parse(
      Buffer.from(data.content, 'base64').toString('utf8'),
    );
    return {
      sha: data.sha,
      registry: {
        claVersion: parsed.claVersion || CLA_VERSION,
        signatures: Array.isArray(parsed.signatures)
          ? parsed.signatures
          : [],
      },
    };
  } catch (error) {
    if (error.status !== 404) {
      throw error;
    }
    return {
      sha: null,
      registry: { claVersion: CLA_VERSION, signatures: [] },
    };
  }
}

function signatureKey(entry) {
  return `${String(entry.githubUser || '').toLowerCase()}::${entry.claVersion || ''}`;
}

function mergeSignatures(base, incoming) {
  const byKey = new Map();
  for (const entry of [...base, ...incoming]) {
    const key = signatureKey(entry);
    if (key === '::') {
      continue;
    }
    if (!byKey.has(key)) {
      byKey.set(key, entry);
    }
  }
  return [...byKey.values()];
}

async function saveRegistry(registry, sha, message) {
  const content = Buffer.from(
    `${JSON.stringify(registry, null, 2)}\n`,
    'utf8',
  ).toString('base64');
  if (sha) {
    await github.rest.repos.createOrUpdateFileContents({
      owner,
      repo,
      path: SIGNATURES_PATH,
      message,
      content,
      sha,
      branch: SIGNATURES_BRANCH,
    });
    return;
  }
  const blob = await github.rest.git.createBlob({
    owner,
    repo,
    content,
    encoding: 'base64',
  });
  const tree = await github.rest.git.createTree({
    owner,
    repo,
    tree: [
      {
        path: SIGNATURES_PATH,
        mode: '100644',
        type: 'blob',
        sha: blob.data.sha,
      },
    ],
  });
  const commit = await github.rest.git.createCommit({
    owner,
    repo,
    message,
    tree: tree.data.sha,
    parents: [],
  });
  try {
    await github.rest.git.createRef({
      owner,
      repo,
      ref: `refs/heads/${SIGNATURES_BRANCH}`,
      sha: commit.data.sha,
    });
  } catch (error) {
    if (error.status !== 422) {
      throw error;
    }
    await github.rest.repos.createOrUpdateFileContents({
      owner,
      repo,
      path: SIGNATURES_PATH,
      message,
      content,
      branch: SIGNATURES_BRANCH,
    });
  }
}

async function publishPullRequestResult(headSha, success, summary) {
  await github.rest.checks.create({
    owner,
    repo,
    name: CHECK_NAME,
    head_sha: headSha,
    status: 'completed',
    conclusion: success ? 'success' : 'failure',
    output: {
      title: success
        ? 'CLA signatures complete'
        : 'CLA signatures missing',
      summary,
    },
  });

  if (context.eventName !== 'issue_comment' || !success) {
    return;
  }

  const runs = await github.paginate(
    github.rest.actions.listWorkflowRunsForRepo,
    { owner, repo, head_sha: headSha, per_page: 30 },
  );
  const prior = runs.find(
    (run) =>
      run.name === CHECK_NAME &&
      run.event === 'pull_request' &&
      run.conclusion === 'failure',
  );
  if (!prior) {
    return;
  }
  try {
    await github.rest.actions.reRunWorkflow({
      owner,
      repo,
      run_id: prior.id,
    });
  } catch (error) {
    core.warning(
      `Could not re-run the pull-request CLA workflow: ${error.message}`,
    );
  }
}

const commentBody = String(context.payload.comment?.body || '').trim();
const wantsSignature =
  context.eventName === 'issue_comment' && commentBody === SIGN_PHRASE;

if (context.eventName === 'issue_comment' && !wantsSignature) {
  core.info('Comment is not a CLA signature; skipping.');
  return;
}

const pull = await github.rest.pulls.get({
  owner,
  repo,
  pull_number: pullNumber,
});
const headSha = pull.data.head.sha;

const { sha, registry } = await loadRegistry();
const signedLogins = signedLoginsForCurrentVersion(registry.signatures);

if (wantsSignature) {
  const signer = context.payload.comment.user;
  if (!signer?.login) {
    core.setFailed('CLA signature comment has no GitHub user.');
    return;
  }
  if (!isAllowlisted(signer.login) && !signedLogins.has(signer.login.toLowerCase())) {
    const nextSignature = {
      githubUser: signer.login,
      githubUserId: signer.id,
      signedAt: new Date().toISOString(),
      claVersion: CLA_VERSION,
      repository: `${owner}/${repo}`,
      pullRequest: pullNumber,
      commentUrl: context.payload.comment.html_url,
    };
    let lastError = null;
    for (let attempt = 0; attempt < 5; attempt++) {
      const current = attempt === 0 ? { sha, registry } : await loadRegistry();
      current.registry.claVersion = CLA_VERSION;
      current.registry.signatures = mergeSignatures(
        current.registry.signatures,
        [nextSignature],
      );
      try {
        await saveRegistry(
          current.registry,
          current.sha,
          `Record CLA signature from @${signer.login} on PR #${pullNumber}`,
        );
        registry.signatures = current.registry.signatures;
        signedLogins.add(signer.login.toLowerCase());
        lastError = null;
        break;
      } catch (error) {
        lastError = error;
        if (error.status !== 409 && error.status !== 422) {
          throw error;
        }
      }
    }
    if (lastError) {
      throw lastError;
    }
  }
}

const commits = await github.paginate(github.rest.pulls.listCommits, {
  owner,
  repo,
  pull_number: pullNumber,
});
const authors = new Set();
const unidentified = [];
for (const commit of commits) {
  const login = commit.author?.login || commit.committer?.login;
  if (!login || login === 'web-flow') {
    unidentified.push(commit.sha.slice(0, 7));
    continue;
  }
  authors.add(login);
}
const prUser = pull.data.user?.login;
if (prUser) {
  authors.add(prUser);
}

const missing = [...authors].filter(
  (login) =>
    !isAllowlisted(login) &&
    !signedLoginsForCurrentVersion(registry.signatures).has(
      login.toLowerCase(),
    ),
);
// Bot/app-authored commits often carry only a raw git identity
// (no linked GitHub user). Accept them when the PR author itself
// is an exempt bot; human PRs still fail on unidentified commits.
const complete =
  (unidentified.length === 0 || isAllowlisted(prUser)) &&
  missing.length === 0;

if (complete) {
  const summary = 'All pull request authors are allowlisted or have signed the current CLA version.';
  await publishPullRequestResult(headSha, true, summary);
  core.info(summary);
  return;
}

const body = [
  MARKER,
  'This pull request needs a CLA signature before it can be merged.',
  '',
  `Read [\`CLA.md\`](https://github.com/${owner}/${repo}/blob/main/CLA.md), then comment exactly:`,
  '',
  `\`${SIGN_PHRASE}\``,
  '',
  missing.length
    ? `Unsigned GitHub users: ${missing.map((login) => `@${login}`).join(', ')}.`
    : '',
  unidentified.length
    ? `Commits without a GitHub user: ${unidentified.join(', ')}.`
    : '',
  '',
  'A checklist box is not a signature. The workflow records your GitHub identity, current CLA version, timestamp, repository, and pull request number.',
]
  .filter((line) => line !== '')
  .join('\n');

const comments = await github.paginate(github.rest.issues.listComments, {
  owner,
  repo,
  issue_number: pullNumber,
});
const existing = comments.find((comment) =>
  String(comment.body || '').includes(MARKER),
);
if (existing) {
  await github.rest.issues.updateComment({
    owner,
    repo,
    comment_id: existing.id,
    body,
  });
} else {
  await github.rest.issues.createComment({
    owner,
    repo,
    issue_number: pullNumber,
    body,
  });
}

await publishPullRequestResult(headSha, false, body);
core.setFailed(
  unidentified.length
    ? 'CLA signatures are missing, or some commits have no GitHub user.'
    : `CLA signatures missing for: ${missing.join(', ')}`,
);

